/* Single-career learning flow. Frozen curriculum supplies every question, excerpt and knowledge identity. */
(function(){
'use strict';
const VERSION='local-workbench-0.14-dialog-detail',KEY='rolecraft-experience-v13',CURRENT='textbook-v12';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>typeof v==='string'?v:'';
const empty=()=>({schemaVersion:'1',corpusVersion:CURRENT,corpusHash:globalThis.RolecraftContentV12?.corpusHash,marks:{},preferences:{startingPoint:null,fontSize:16,courseView:'roadmap'},quiz:null});
let state=empty(),savedRaw=null,saveError='',activeView='home',recordTab='learned',scale=1,routeFilter='all',reviewIndex=0,reviewIds=[],listScroll=0;
const corpus=()=>globalThis.RolecraftContentV12;
const id=k=>k?.knowledgePointId||k?.id;
const metadata=d=>d;
let validatedPackage=null,validatedCorpus=null,packageValid=false;
function data(){const d=globalThis.RolecraftLearningV13,c=corpus();if(d===validatedPackage&&c===validatedCorpus)return packageValid?d:null;validatedPackage=d;validatedCorpus=c;packageValid=false;try{
 if(!d||d.corpusVersion!==CURRENT||d.corpusHash!==c?.corpusHash||d.bookSha256!==c.bookSha256||d.units.length!==30||d.questions.length!==114||d.knowledgePoints.length!==240)throw Error('data identity');
 const ks=new Map(d.knowledgePoints.map(k=>[k.id,k]));
 for(const [i,u]of d.units.entries()){const original=c.units[i];if(original.unitId!==u.unitId||original.sourceSha256!==u.sourceSha256||original.sourcePath!==u.sourcePath)throw Error('source identity');}
 for(const k of d.knowledgePoints){const u=c.units.find(u=>u.unitId===k.unitId),sec=u?.sections.find(s=>s.sectionId===k.sectionId);if(!sec||sec.title!==k.title||u.sourceSha256!==k.sourceSha256||k.href!==sec.href||!k.childSectionIds.every(sid=>u.sections.some(s=>s.sectionId===sid)))throw Error('knowledge identity');}
 for(const q of d.questions){if(!q.question||!q.knowledgeRefs.length)throw Error('question identity');for(const e of [...q.knowledgeRefs,...q.evidence]){const u=c.units.find(u=>u.unitId===e.unitId),sec=u?.sections.find(s=>s.sectionId===e.sectionId),k=ks.get(e.knowledgePointId);if(!u||!sec||!k||e.sourceSha256!==u.sourceSha256||e.sourcePath!==u.sourcePath||e.sectionTitle!==sec.title||e.href!==sec.href||!(k.sectionId===sec.sectionId||k.childSectionIds.includes(sec.sectionId)))throw Error('reference identity');if(e.quote&&(!sec.bodyMarkdown.includes(e.quote)||!u.bodyMarkdown.split('\n').slice(e.startLine-1,e.endLine).join('\n').includes(e.quote)))throw Error('quote identity');}}
 packageValid=true;return d;
 }catch{return null;}}

const unit=uid=>corpus()?.units.find(u=>u.unitId===uid);
const kp=kid=>data()?.knowledgePoints.find(k=>id(k)===kid);
const question=qid=>typeof qid==='string'&&qid?data()?.questions.find(q=>q.id===qid||q.questionId===qid):null;
const qid=q=>q?.questionId||q?.id;
const refs=q=>(q?.knowledgeRefs||[]).map(r=>typeof r==='string'?kp(r):kp(r.knowledgePointId||r.id)).filter(Boolean);
const qFor=k=>(k?.questionIds||[]).map(question).filter(Boolean);
const learnHref=k=>k?.href||'#learn';
const route=()=>{const [p,s='']=location.hash.slice(1).split('?');return{parts:p.split('/'),params:new URLSearchParams(s)};};
const queryHref=(params={},questionId='')=>'#questions'+(questionId?'/'+questionId:'')+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
function safeQuestionFilters(params,prefix=''){const out={};for(const name of ['unit','kp','state','set']){const key=prefix?prefix+name[0].toUpperCase()+name.slice(1):name,value=params.get(key);if(!value)continue;if(name==='unit'&&data()?.units.some(u=>u.unitId===value)||name==='kp'&&kp(value)||name==='state'&&['weak','known'].includes(value)||name==='set'&&['fixed','market'].includes(value))out[name]=value;}if(out.unit&&out.kp&&kp(out.kp)?.unitId!==out.unit)delete out.kp;return out;}
function questionReadingHref(target,q){const params=new URLSearchParams({from:qid(q)}),r=route();if(r.parts[0]==='questions')for(const [name,value]of Object.entries(safeQuestionFilters(r.params)))params.set('from'+name[0].toUpperCase()+name.slice(1),value);return target+(target.includes('?')?'&':'?')+params;}

function redraw(){if(typeof render==='function')render();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveError='';return true;}catch{saveError='无法保存到浏览器，当前操作仍在页面中；请导出后再关闭。';return false;}}
try{savedRaw=localStorage.getItem(KEY);if(savedRaw){const s=JSON.parse(savedRaw);if(s.corpusVersion!==CURRENT||s.corpusHash!==corpus()?.corpusHash)throw Error('Record version mismatch');state={...empty(),...s,marks:s.marks&&typeof s.marks==='object'?s.marks:{},preferences:{...empty().preferences,...s.preferences}};}}catch{saveError='已有记录无法解析或来源不同；原值仍可导出，当前未据此显示学习状态。';}
function markStatus(q){const m=state.marks[qid(q)];return m&&m.corpusHash===corpus()?.corpusHash&&m.dataVersion===metadata(data())?.version&&['weak','known'].includes(m.status)?m.status:'';}
function mark(q,status){if(!q||!data())return;const key=qid(q);if(markStatus(q)===status||!status)delete state.marks[key];else state.marks[key]={status,corpusVersion:CURRENT,corpusHash:corpus().corpusHash,dataVersion:metadata(data()).version,at:new Date().toISOString()};save();}
function ownership(uid,sid){const d=data();if(!d)return null;const mapping=(d.sectionOwnership||d.sectionMap||[]);const entry=Array.isArray(mapping)?mapping.find(m=>m.unitId===uid&&m.sectionId===sid):mapping[uid]?.[sid];const declared=entry?.knowledgePointId||entry?.id||(typeof entry==='string'?entry:null);if(declared)return kp(declared);return d.knowledgePoints.find(k=>k.unitId===uid&&(k.sectionId===sid||k.childSectionIds?.includes(sid)))||null;}
function learned(){const visits=globalThis.LearningWorkbench?.readingRecords?.().visits||[],result=new Map();for(const v of visits){if(!LearningWorkbench.recordIsCurrent(v))continue;const u=unit(v.unitId),s=v.sectionId||u?.sections[0]?.sectionId,k=ownership(v.unitId,s);if(k&&k.kind!=='navigation')result.set(id(k),{knowledgePoint:k,at:v.at});}return Array.from(result.values()).sort((a,b)=>String(b.at).localeCompare(String(a.at)));}
const isLearned=k=>learned().some(v=>id(v.knowledgePoint)===id(k));
const knowledgeState=k=>qFor(k).some(q=>markStatus(q)==='weak')?'weak':isLearned(k)?'learned':'unseen';
const statusText={weak:'有未掌握题',learned:'已学习（访问过）',unseen:'未学习'};
const badge=(s,label)=>'<span class="v13-status '+s+'">'+esc(label||statusText[s])+'</span>';
const unitKnowledge=uid=>data()?.knowledgePoints.filter(k=>k.unitId===uid)||[];
function unitState(u){const ks=unitKnowledge(u.unitId);return ks.some(k=>knowledgeState(k)==='weak')?'weak':ks.some(isLearned)?'learned':'unseen';}
function issue(message='课程关联资料暂不可用；正文仍可正常阅读。'){return '<div class="v13-empty" role="alert"><p>'+esc(message)+'</p><a class="outline" href="#learn">阅读教材</a></div>';}
const heading=(title,desc)=>'<div class="v13-page-head"><h1 tabindex="-1">'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>';
const button=(label,attrs,selected=false)=>'<button class="outline'+(selected?' selected':'')+'" '+attrs+' aria-pressed="'+selected+'">'+label+'</button>';
function knowledgeLink(k,fromQuestion){const target=fromQuestion&&typeof fromQuestion==='object'&&qid(fromQuestion)?questionReadingHref(learnHref(k),fromQuestion):learnHref(k),status=knowledgeState(k);if(k.kind==='navigation')return '<a class="v13-knowledge-link" href="'+esc(target)+'"><span>'+esc(k.title)+'</span><small>导航参考</small></a>';return '<a class="v13-knowledge-link" href="'+esc(target)+'"><span>'+esc(k.title)+'</span>'+badge(status)+'</a>';}
function latestVisit(){return (LearningWorkbench.readingRecords().visits||[]).filter(LearningWorkbench.recordIsCurrent).at(-1);}
function unitHasReading(u){return (LearningWorkbench.readingRecords().visits||[]).some(v=>v.unitId===u.unitId&&LearningWorkbench.recordIsCurrent(v));}
function browsingBook(open){return '<svg class="v14-browse-icon" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(open?'<path d="M12 5.5C8.9 3.7 5.8 3.6 2.8 4.9v14.6c3-1.3 6.1-1.2 9.2.6 3.1-1.8 6.2-1.9 9.2-.6V4.9c-3-1.3-6.1-1.2-9.2.6Z"/><path d="M12 5.5v14.6"/>':'<path d="M6 3.5h11.5v17H6a2 2 0 0 1 0-4h11.5M6 3.5a2 2 0 0 0-2 2v13"/>')+'</svg>';}

function continuation(){const v=latestVisit(),u=unit(v?.unitId)||corpus()?.units[0],name=u?.navigationLabel||'认识 Agent',action=v?'继续阅读':'开始阅读';return '<div class="v13-continue v14-compact-resume"><span>'+esc(action+' · '+name)+'</span><a href="#learn/agent/'+esc(u?.unitId||'00-learning-route')+(v?.sectionId?'/'+esc(v.sectionId):'')+'" aria-label="'+esc(action+'：'+name)+'">'+(v?'继续':'开始')+' →</a></div>';}
function coursePage(){
 const c=corpus();if(!c)return issue('教材资源暂不可用。');
 const d=data(),stages=d?.routeStages||[{title:'Agent 工程学习路线',unitIds:c.units.map(u=>u.unitId)}];
 // Former view/filter preferences remain stored; this page always presents the full route.
 scale=1;routeFilter='all';
 const content='<div class="v13-map-viewport" id="v13-map-viewport" tabindex="0" aria-label="学习路线图，可滚动"><div class="v13-map-space" id="v13-map-space"><div class="v13-map-canvas" id="v13-map-canvas">'+stages.map((stage,i)=>{const us=(stage.unitIds||stage.ids||[]).map(unit).filter(Boolean);return us.length?'<section class="v13-map-stage"><h2><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(stage.title)+'</h2><div class="v13-map-nodes">'+us.map(u=>{const browsed=unitHasReading(u);return '<article class="v13-route-node v14-reading-node '+(browsed?'has-reading':'no-reading')+'"><a class="v13-node-main" href="#learn/agent/'+u.unitId+'"><span class="v13-num">'+String(u.order).padStart(2,'0')+'</span><strong>'+esc(u.navigationLabel)+'</strong>'+browsingBook(browsed)+'<span class="v14-node-sr">'+(browsed?'本版有阅读记录':'本版暂无阅读记录')+'</span></a><details><summary>知识点 '+unitKnowledge(u.unitId).length+'</summary><div class="v13-branches">'+unitKnowledge(u.unitId).map(knowledgeLink).join('')+'</div></details></article>';}).join('')+'</div></section>':'';}).join('')+'</div></div></div>';
 return '<div class="v13-course">'+heading('Agent 开发学习路线','从理解 Agent，到实现、验证与交付自己的产品')+continuation()+content+'</div>';
}
function markButtons(q){const s=markStatus(q);return '<div class="v13-mark-actions">'+button(s==='weak'?'未掌握 · 取消':'未掌握','data-v13-mark="weak" data-v13-question="'+qid(q)+'"',s==='weak')+(s?button(s==='known'?'已掌握（自评）· 取消':'已掌握（自评）','data-v13-mark="known" data-v13-question="'+qid(q)+'"',s==='known'):'')+'</div>';}
function evidenceHTML(q){return '<div class="v13-reference-analysis"><h2>教材参考分析（原文摘录）</h2><p class="v13-small">来自当前 v12 教材，帮助你核对机制；不是自动生成的固定标准答案。</p>'+ (q.personalEvidenceRequired||q.answerKind==='personal_evidence_required'?'<div class="lw-message">这道题需要结合你的真实经历。教材只提供方法，不能代替你的项目事实，也不进入自评抽题。</div>':'')+(q.evidence||[]).map(e=>'<section class="v13-evidence"><h3>'+esc(e.sectionTitle||unit(e.unitId)?.sections.find(s=>s.sectionId===e.sectionId)?.title||'教材原文')+'</h3><blockquote>'+esc(e.quote||e.excerpt)+'</blockquote><a href="'+esc(questionReadingHref(e.href,q))+'">阅读这一节 →</a><details><summary>查看出处</summary><p>'+esc(e.sourcePath)+' · 第 '+esc(e.startLine||e.lineStart)+'–'+esc(e.endLine||e.lineEnd)+' 行</p><code>'+esc(e.sourceSha256)+'</code></details></section>').join('')+'</div>';}
function questionCard(q,p={}){return '<article class="v13-question-card"><div><small>'+esc(qid(q))+' · '+(q.set==='market'||qid(q).startsWith('M')?'市场补充题组':'固定题组')+'</small><a class="v13-question-title" href="'+esc(queryHref(p,qid(q)))+'">'+esc(q.prompt||q.questionText||q.question)+'</a><div class="v13-question-tags">'+refs(q).map(k=>'<a href="'+esc(questionReadingHref(learnHref(k),q))+'">'+esc(k.title)+'</a>').join('')+'</div></div>'+markButtons(q)+'</article>';}
function filteredQuestions(p){return (data()?.questions||[]).filter(q=>(!p.get('unit')||refs(q).some(k=>k.unitId===p.get('unit')))&&(!p.get('kp')||refs(q).some(k=>id(k)===p.get('kp')))&&(!p.get('state')||markStatus(q)===p.get('state'))&&(!p.get('set')||(p.get('set')==='market'?qid(q).startsWith('M'):qid(q).startsWith('Q'))));}
function questionPage(){const d=data(),r=route(),q=question(r.parts[1]);if(!d)return issue('题库资料暂不可用；不会用演示题替代。');if(r.parts[1]&&!q)return issue('该题目不存在于当前题组。');
 if(q){const qs=filteredQuestions(r.params),i=qs.findIndex(x=>qid(x)===qid(q));return '<div class="v13-question-detail"><a class="v13-back" href="'+esc(queryHref(Object.fromEntries(r.params)))+'">← 返回题库</a>'+heading(qid(q)+' · 题目详情',q.personalEvidenceRequired?'需结合你的真实经历':'先独立思考，再核对教材')+'<h2 class="v13-full-question">'+esc(q.prompt||q.questionText||q.question)+'</h2><details class="v13-answer"><summary>查看教材参考分析</summary>'+evidenceHTML(q)+'</details>'+markButtons(q)+'<section><h2>关联知识点</h2>'+refs(q).map(k=>knowledgeLink(k,q)).join('')+'</section><nav class="lw-pagination">'+(i>0?'<a href="'+esc(queryHref(Object.fromEntries(r.params),qid(qs[i-1])))+'">← 上一题</a>':'<span></span>')+(i>=0&&i<qs.length-1?'<a href="'+esc(queryHref(Object.fromEntries(r.params),qid(qs[i+1])))+'">下一题 →</a>':'<span></span>')+'</nav></div>';}
 const qs=filteredQuestions(r.params),uid=r.params.get('unit')||'';return '<div class="v13-bank">'+heading('题库浏览','从问题查缺，再回到教材读懂机制')+'<form class="v13-question-filters" id="v13-question-filters"><label>课程<select name="unit"><option value="">全部课程</option>'+d.units.map(u=>'<option value="'+u.unitId+'"'+(uid===u.unitId?' selected':'')+'>'+esc(unit(u.unitId)?.navigationLabel)+'</option>').join('')+'</select></label><label>知识点<select name="kp"><option value="">全部知识点</option>'+d.knowledgePoints.filter(k=>!uid||k.unitId===uid).map(k=>'<option value="'+esc(id(k))+'"'+(r.params.get('kp')===id(k)?' selected':'')+'>'+esc(k.title)+'</option>').join('')+'</select></label><label>本人标注<select name="state"><option value="">全部状态</option><option value="weak"'+(r.params.get('state')==='weak'?' selected':'')+'>未掌握</option><option value="known"'+(r.params.get('state')==='known'?' selected':'')+'>已掌握（自评）</option></select></label><label>题组<select name="set"><option value="">全部题组（100 + 14）</option><option value="fixed"'+(r.params.get('set')==='fixed'?' selected':'')+'>固定100题</option><option value="market"'+(r.params.get('set')==='market'?' selected':'')+'>市场补充14题</option></select></label><button class="outline" type="submit">应用筛选</button><a href="#questions">清除筛选</a></form><p class="v13-small">当前 '+qs.length+' 题。按冻结题号排列；状态为本人自记，没有平台热度或频次排名。</p><div class="v13-question-list">'+(qs.length?qs.map(q=>questionCard(q,Object.fromEntries(r.params))).join(''):issue('筛选范围暂无题目。'))+'</div></div>';}
function relatedReader(html){const r=route();if(r.parts[0]!=='learn'||r.params.get('version')==='textbook-v10')return html;const u=unit(r.parts[2]);if(!u)return html;const block=['p01-discovery','02-task-acceptance','p01-mvp','p02'].includes(u.unitId)?'<section class="v13-reader-project"><a class="outline" href="#projects">记录我的项目 →</a></section>':'';const back=r.params.get('from');if(back&&question(back))html='<a class="v13-back" href="'+esc(queryHref(safeQuestionFilters(r.params,'from'),back))+'">← 回到原题 '+esc(back)+'</a>'+html;return html.replace('<section class="lw-note-area">',block+'<section class="lw-note-area">');}
function recordsPage(){const d=data(),entries=learned(),weak=(d?.questions||[]).filter(q=>markStatus(q)==='weak'),known=(d?.questions||[]).filter(q=>markStatus(q)==='known');const existing=LearningWorkbench.page('records');const detail=existing.slice(existing.indexOf('<div class="lw-record-toolbar">'));return '<div class="v13-records">'+heading('学习记录','接着读、回到疑问，再用一次自评查缺')+'<div class="v13-quick-cards"><section><h2>继续学习</h2><p>'+esc(latestVisit()?unit(latestVisit().unitId)?.navigationLabel:'先从认识 Agent 开始')+'</p><a class="primary" href="'+(latestVisit()?'#learn/agent/'+latestVisit().unitId+(latestVisit().sectionId?'/'+latestVisit().sectionId:''):'#learn')+'">'+(latestVisit()?'继续阅读':'查看路线')+' →</a></section><section><h2>复习</h2><p>'+ (weak.length?'有 '+weak.length+' 道本人未掌握题':'目前没有待复习题')+'</p><a class="outline" href="'+(weak.length?'#review':'#questions')+'">'+(weak.length?'开始复习':'去题库标注')+' →</a></section><section><h2>检验学习结果</h2><p>从你看过的知识点出题，结果只作本次自评。</p><a class="outline" href="#check">查看可用题目 →</a></section></div><div class="v13-segment">'+[['learned','已学习'],['weak','未掌握'],['known','已掌握（自评）']].map(([v,label])=>button(label,'data-v13-record-tab="'+v+'"',recordTab===v)).join('')+'</div><div class="v13-record-list">'+(recordTab==='learned'?(entries.length?entries.map(v=>'<article><div><a href="'+esc(learnHref(v.knowledgePoint))+'">'+esc(v.knowledgePoint.title)+'</a><p>'+esc(unit(v.knowledgePoint.unitId)?.navigationLabel)+' · '+esc(new Date(v.at).toLocaleString('zh-CN'))+'</p></div><a class="outline" href="'+esc(queryHref({unit:v.knowledgePoint.unitId,kp:id(v.knowledgePoint)}))+'">做配套题目</a></article>').join(''):issue('还没有当前版知识点访问记录，先打开一个知识点学习。')):(recordTab==='weak'?weak:known).map(q=>questionCard(q)).join('')||issue('此列表暂无本人标注。'))+'</div><section class="v13-project-entry"><h2>我的项目记录</h2><p>保存问题、证据、作品结果和改进；都是本人自述。</p><a class="outline" href="#projects">记录与查看项目 →</a></section><details class="v13-record-details"><summary>收藏、笔记与历史学习记录</summary>'+detail+'</details></div>';}
function eligible(){const ids=new Set(learned().flatMap(v=>v.knowledgePoint.questionIds||[]));return (data()?.questions||[]).filter(q=>ids.has(qid(q))&&q.selfTestEligible!==false&&!q.excludeFromSelfTest&&!q.personalEvidenceRequired&&q.answerKind!=='personal_evidence_required');}
function reviewPage(){const weak=(data()?.questions||[]).filter(q=>markStatus(q)==='weak');if(!reviewIds.length)reviewIds=weak.map(qid);const available=reviewIds.map(question).filter(q=>q&&markStatus(q)==='weak');if(route().parts[1]==='done'||!available.length||reviewIndex>=available.length)return heading('复习','本次复习已结束')+issue('目前没有本人未掌握题，可回题库继续学习。');if(route().parts[1]&&available.some(q=>qid(q)===route().parts[1]))reviewIndex=available.findIndex(q=>qid(q)===route().parts[1]);reviewIndex=Math.max(0,Math.min(reviewIndex,available.length-1));const q=available[reviewIndex];return '<div class="v13-question-detail">'+heading('复习 · '+(reviewIndex+1)+' / '+available.length,'先回想，再看教材参考；是否掌握由你自记')+'<h2>'+esc(q.prompt||q.questionText||q.question)+'</h2><details class="v13-answer"><summary>查看教材参考分析</summary>'+evidenceHTML(q)+'</details><div class="v13-actions">'+button('仍未掌握，下一题','data-v13-review-next')+button('已掌握（自评），下一题','data-v13-review-known="'+qid(q)+'"')+'</div><div class="v13-question-tags">'+refs(q).map(k=>'<a href="'+esc(learnHref(k))+'">学习：'+esc(k.title)+'</a>').join('')+'</div><nav class="lw-pagination">'+button('上一题','data-v13-review-prev')+button('下一题','data-v13-review-next')+'</nav><a href="#records">返回学习记录</a></div>';}
function checkPage(){const quiz=state.quiz,pool=eligible();if(!quiz)return '<div class="v13-question-detail">'+heading('检验学习结果','仅抽取当前版已访问知识点对应的适用题')+'<p>目前可用 '+pool.length+' 题，排除需真实经历的题目。数量不足时使用全部可用题，不重复补足。</p><label for="v13-check-count">本次题数</label><select id="v13-check-count"><option>5</option><option>10</option><option>20</option></select>'+ (pool.length?'<button class="primary" data-v13-start-check>开始本次自评</button>':issue('目前还没有已学知识点对应的可自评题，先打开一个知识点学习。'))+'</div>';
 if(quiz.index>=quiz.ids.length){const counts={correct:0,wrong:0,skip:0};for(const a of Object.values(quiz.responses||{}))if(a.outcome in counts)counts[a.outcome]++;return '<div class="v13-question-detail">'+heading('本次自评已结束','本人判断，未作机器评分或专业考试')+'<div class="v13-self-counts"><p>自评答对 '+counts.correct+'</p><p>自评答错 '+counts.wrong+'</p><p>跳过 '+counts.skip+'</p></div>'+(quiz.ids.map(question).filter(Boolean).map(q=>questionCard(q)).join(''))+'<button class="outline" data-v13-new-check>重新选择题目</button><a href="#records">返回学习记录</a></div>';}
 const q=question(quiz.ids[quiz.index]);if(!q||!pool.some(x=>qid(x)===qid(q)))return issue('本次自评来源或已学范围已变化，请返回记录重新开始。');const answer=quiz.responses[qid(q)]?.answer||'';return '<div class="v13-question-detail">'+heading('本次自评 · '+(quiz.index+1)+' / '+quiz.ids.length,'先作答或默答，再看教材原文，最后由你自评')+(quiz.ids.length<quiz.requested?'<p class="v13-small">适用题不足 '+quiz.requested+' 道，本次使用全部 '+quiz.ids.length+' 道，不重复补足。</p>':'')+'<h2>'+esc(q.prompt||q.questionText||q.question)+'</h2><label for="v13-own-answer">我的回答（可默答后直接核对）</label><textarea id="v13-own-answer" rows="5" maxlength="12000">'+esc(answer)+'</textarea><details class="v13-answer"><summary>查看教材参考分析</summary>'+evidenceHTML(q)+'</details><label class="v13-check-label"><input type="checkbox" id="v13-add-wrong" checked> 如果我自评答错，加入未掌握列表</label><div class="v13-actions">'+button('我答对了（自评）','data-v13-outcome="correct"')+button('我答错了（自评）','data-v13-outcome="wrong"')+button('跳过','data-v13-outcome="skip"')+'</div><p class="v13-small">答对不会自动把题目标为已掌握；题状态仍由你明确标注。</p></div>';}
function settingsPage(){const p=state.preferences;return '<div class="v13-settings">'+heading('个人设置','调整阅读偏好，管理本浏览器的记录')+'<section><h2>学习偏好</h2><label for="v13-starting">我的起点</label><select id="v13-starting"><option value="">尚未选择</option>'+[['beginner','零基础'],['developer','已有编程基础'],['practitioner','已有 Agent 项目经验']].map(([v,label])=>'<option value="'+v+'"'+(p.startingPoint===v?' selected':'')+'>'+label+'</option>').join('')+'</select><label for="v13-font-size">正文字号</label><select id="v13-font-size">'+[16,18,20].map(n=>'<option value="'+n+'"'+(Number(p.fontSize)===n?' selected':'')+'>'+n+'px'+(n===16?' · 标准':'')+'</option>').join('')+'</select><p class="v13-small">起点用于本人偏好和查教材上下文，不是 AI 能力诊断。</p></section><section><h2>记录与保存</h2><p>本机学习者 · 仅当前浏览器，未同步账户。</p><button class="outline" data-v13-export>导出当前与历史记录</button><p>没有接入短信、微信或跨设备同步，不需登录即可阅读、标记和保存。</p></section><section><h2>教材说明</h2><p>当前教材 v12，30 篇；题库使用100固定题与14市场补充题的真实题面及教材摘录。</p><details><summary>查看来源与能力范围</summary><p>AI 文稿和有限验证不等于真人专家认可、学员胜任或行业先进。查教材使用当前本地真实内容检索，教材生成、语音及外部动态回答本轮未接入。</p><p>教材 SHA256：<code>'+esc(corpus()?.bookSha256)+'</code></p></details></section><section><details><summary>历史资料与研发工具</summary><p>用于研究和开发查阅，旧记录、正文与审核范围保持原身份。</p><div class="v13-history-links">'+Object.entries({book:'历史教材与测验','history-home':'历史学习概览','history-path':'历史职业路线','projects-history':'历史项目记录',standards:'能力标准',curriculum:'原课程地图',creation:'产品实作路线','product-review':'产品达标复盘',reflections:'学习与员工复盘',sources:'知识来源',generation:'单章生成研发'}).map(([v,label])=>'<a href="#'+v+'">'+label+'</a>').join('')+'</div></details></section></div>';}
function exportAll(){const oldKeys=['rolecraft-v1','rolecraft-learning-v11','rolecraft-learning-v12'];const original={};for(const k of oldKeys){try{original[k]=localStorage.getItem(k);}catch{original[k]=null;}}const payload={version:VERSION,scope:'本人阅读记录、题目标注和自评，不是独立能力认证',learning:LearningWorkbench.recordsExportData(),experience:state,originalEarlierStorage:original,receivedExperienceRaw:savedRaw};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='职造-本地学习与历史记录-v13.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function applyMap(){const canvas=document.getElementById('v13-map-canvas'),space=document.getElementById('v13-map-space');if(canvas&&space){canvas.style.transform='scale('+scale+')';space.style.width=canvas.offsetWidth*scale+'px';space.style.height=canvas.offsetHeight*scale+'px';const label=document.getElementById('v13-zoom-label');if(label)label.textContent=Math.round(scale*100)+'%';}}
function page(view){if(['home','path'].includes(view)||view==='learn'&&!route().parts[2])return coursePage();if(view==='learn')return relatedReader(LearningWorkbench.page('learn'));if(view==='questions')return questionPage();if(view==='records')return recordsPage();if(view==='review')return reviewPage();if(view==='check')return checkPage();if(view==='settings')return settingsPage();if(view==='projects')return '<a class="v13-back" href="#records">← 返回学习记录</a>'+LearningWorkbench.page('projects');return '';}
function mount(view){activeView=view;document.body.dataset.learningPage=(['home','path'].includes(view)||view==='learn'&&!route().parts[2])?'course-home':view;document.body.classList.add('v13-active');document.documentElement.style.setProperty('--reader-font',([16,18,20].includes(Number(state.preferences.fontSize))?state.preferences.fontSize:16)+'px');const titles={home:['Agent 开发学习路线','从理解 Agent，到实现、验证与交付自己的产品'],learn:['课程学习','读懂机制，再回到自己的问题'],path:['Agent 开发学习路线','按需阅读，也可以沿推荐顺序学习'],questions:['题库浏览','从问题查缺，再回到教材'],review:['复习','本人未掌握题，逐题回想与核对'],check:['检验学习结果','从看过的知识点出题，只作本人自评'],records:['学习记录','回到你需要的地方'],projects:['我的项目记录','实际作品与本人自述'],settings:['个人设置','阅读偏好与本浏览器记录']};const t=titles[view]||['历史资料与研发记录','原版本与证据范围保持'];const title=document.getElementById('breadcrumb');if(title)title.textContent=t[0];const sub=document.getElementById('page-subtitle');if(sub)sub.textContent=t[1];const banner=document.getElementById('save-status');if(banner){banner.textContent=saveError||'';banner.hidden=!saveError;}
 const sidebar=document.getElementById('primary-sidebar');sidebar?.classList.remove('is-open');if(sidebar){sidebar.inert=globalThis.innerWidth<=760;sidebar.setAttribute('aria-hidden',String(sidebar.inert));}document.getElementById('mobile-menu')?.setAttribute('aria-expanded','false');applyMap();const viewport=document.getElementById('v13-map-viewport');if(viewport){let drag=null;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('a,button,summary'))return;drag={x:e.clientX,y:e.clientY,l:viewport.scrollLeft,t:viewport.scrollTop};});viewport.addEventListener('pointermove',e=>{if(!drag||!e.buttons)return;viewport.scrollLeft=drag.l-e.clientX+drag.x;viewport.scrollTop=drag.t-e.clientY+drag.y;});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointerleave',()=>drag=null);viewport.querySelectorAll('details').forEach(n=>n.addEventListener('toggle',applyMap));}LearningWorkbench.refreshAssistant();if(view==='questions'&&!route().parts[1]&&listScroll)requestAnimationFrame(()=>window.scrollTo(0,listScroll));}
function queryContext(){const r=route(),q=['questions'].includes(r.parts[0])?question(r.parts[1]):r.parts[0]==='review'?(question(r.parts[1])||reviewIds.map(question).filter(q=>q&&markStatus(q)==='weak')[reviewIndex]):r.parts[0]==='check'?question(state.quiz?.ids[state.quiz?.index]):null;const k=refs(q)[0];return k?{unitId:k.unitId,sectionId:k.sectionId}:null;}
function inputHint(){return '描述 Agent 开发、学习或项目中的问题';}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.id==='mobile-menu'){const nav=document.getElementById('primary-sidebar'),open=nav.classList.toggle('is-open');el.setAttribute('aria-expanded',String(open));nav.inert=!open;nav.setAttribute('aria-hidden',String(!open));return;}if(el.dataset.v13CourseView){state.preferences.courseView=el.dataset.v13CourseView;save();redraw();return;}if(el.dataset.v13RouteFilter){routeFilter=el.dataset.v13RouteFilter;redraw();return;}if(el.hasAttribute('data-v13-zoom')){scale=Math.max(.6,Math.min(1.6,scale+Number(el.dataset.v13Zoom)));applyMap();return;}if(el.hasAttribute('data-v13-reset-map')){scale=1;const v=document.getElementById('v13-map-viewport');if(v){v.scrollLeft=0;v.scrollTop=0;}applyMap();return;}if(el.dataset.v13Pan){const v=document.getElementById('v13-map-viewport'),dir=el.dataset.v13Pan;if(v){if(dir==='left'||dir==='right')v.scrollLeft+=(dir==='left'?-160:160);else v.scrollTop+=(dir==='up'?-160:160);}return;}if(el.dataset.v13Mark){mark(question(el.dataset.v13Question),el.dataset.v13Mark);redraw();return;}if(el.dataset.v13RecordTab){recordTab=el.dataset.v13RecordTab;redraw();return;}if(el.hasAttribute('data-v13-export')){exportAll();return;}if(el.hasAttribute('data-v13-review-prev')||el.hasAttribute('data-v13-review-next')||el.dataset.v13ReviewKnown){const available=reviewIds.map(question).filter(q=>q&&markStatus(q)==='weak'),current=available.findIndex(q=>qid(q)===route().parts[1]),i=current>=0?current:reviewIndex,next=el.hasAttribute('data-v13-review-prev')?Math.max(0,i-1):i+1;if(el.dataset.v13ReviewKnown)mark(question(el.dataset.v13ReviewKnown),'known');reviewIndex=0;location.hash=next<available.length?'#review/'+qid(available[next]):'#review/done';return;}if(el.hasAttribute('data-v13-start-check')){const count=Number(document.getElementById('v13-check-count')?.value)||5,pool=eligible(),shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}state.quiz={ids:shuffled.slice(0,count).map(qid),requested:count,index:0,responses:{},startedAt:new Date().toISOString()};save();redraw();return;}if(el.hasAttribute('data-v13-new-check')){state.quiz=null;save();redraw();return;}if(el.dataset.v13Outcome&&state.quiz){const q=question(state.quiz.ids[state.quiz.index]),answer=document.getElementById('v13-own-answer')?.value||'';state.quiz.responses[qid(q)]={answer,outcome:el.dataset.v13Outcome};if(el.dataset.v13Outcome==='wrong'&&document.getElementById('v13-add-wrong')?.checked&&markStatus(q)!=='weak')mark(q,'weak');state.quiz.index++;save();redraw();return;}if(el.getAttribute?.('href')==='#review'){reviewIds=(data()?.questions||[]).filter(q=>markStatus(q)==='weak').map(qid);reviewIndex=0;}if(el.closest('.v13-question-list')&&el.tagName==='A')listScroll=window.scrollY;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('primary-sidebar')?.classList.contains('is-open')){const nav=document.getElementById('primary-sidebar');nav.classList.remove('is-open');nav.inert=globalThis.innerWidth<=760;nav.setAttribute('aria-hidden',String(nav.inert));document.getElementById('mobile-menu')?.setAttribute('aria-expanded','false');document.getElementById('mobile-menu')?.focus();}});
document.addEventListener('change',e=>{if(e.target.name==='unit'&&e.target.closest('#v13-question-filters')){const selector=document.querySelector('#v13-question-filters [name=kp]');if(selector)selector.value='';}if(e.target.id==='v13-font-size'){state.preferences.fontSize=Number(e.target.value);save();redraw();}if(e.target.id==='v13-starting'){state.preferences.startingPoint=e.target.value||null;save();redraw();}});
document.addEventListener('submit',e=>{if(e.target.id==='v13-question-filters'){e.preventDefault();const f=new FormData(e.target),p={};for(const [k,v]of f)if(v)p[k]=v;listScroll=0;location.hash=queryHref(p);}});
document.addEventListener('input',e=>{if(e.target.id==='v13-own-answer'&&state.quiz){const key=state.quiz.ids[state.quiz.index];state.quiz.responses[key]={...state.quiz.responses[key],answer:e.target.value.slice(0,12000)};save();}});
globalThis.LearningExperienceV13={version:VERSION,handles:v=>['home','path','learn','questions','review','check','records','settings','projects'].includes(v),page,mount,queryContext,inputHint,startingPoint:()=>state.preferences.startingPoint,learnedKnowledge:learned,eligibleQuestions:eligible,data,knowledgeState,exportAll};
})();
